" class=\"s-line\" stroke-width=\"1\"/><text x=\"20\" y=\"305\" font-size=\"14\">References</text><circle cx=\"160\" cy=\"300\" r=\"6.5\" class=\"f-none s-indigo\" stroke-width=\"2.2\"/><circle cx=\"238\" cy=\"300\" r=\"6.5\" class=\"f-none s-indigo\" stroke-width=\"2.2\"/><circle cx=\"316\" cy=\"300\" r=\"6.5\" class=\"f-none s-indigo\" stroke-width=\"2.2\"/><rect x=\"123\" y=\"326\" width=\"74\" height=\"42\" rx=\"8\" class=\"f-haldi-soft s-haldi\" stroke-width=\"1.5\"/><text x=\"160\" y=\"344\" font-size=\"13\" text-anchor=\"middle\">Keep or</text><text x=\"160\" y=\"360\" font-size=\"13\" text-anchor=\"middle\">drop it?</text><rect x=\"201\" y=\"326\" width=\"74\" height=\"42\" rx=\"8\" class=\"f-haldi-soft s-haldi\" stroke-width=\"1.5\"/><text x=\"238\" y=\"344\" font-size=\"13\" text-anchor=\"middle\">One-page</text><text x=\"238\" y=\"360\" font-size=\"13\" text-anchor=\"middle\">summary</text><rect x=\"279\" y=\"326\" width=\"74\" height=\"42\" rx=\"8\" class=\"f-ok-soft s-ok\" stroke-width=\"1.5\"/><text x=\"316\" y=\"344\" font-size=\"13\" text-anchor=\"middle\">Rebuild</text><text x=\"316\" y=\"360\" font-size=\"13\" text-anchor=\"middle\">it yourself</text><text x=\"16\" y=\"344\" font-size=\"14\" class=\"f-muted\" font-weight=\"700\">You end with</text><text x=\"16\" y=\"361\" font-size=\"13\" class=\"f-muted\">most papers</text><text x=\"16\" y=\"377\" font-size=\"13\" class=\"f-muted\">stop at pass 1</text><circle cx=\"40\" cy=\"399\" r=\"7.5\" class=\"f-indigo\"/><text x=\"53\" y=\"404\" font-size=\"13\">read closely</text><circle cx=\"153\" cy=\"399\" r=\"6.5\" class=\"f-none s-indigo\" stroke-width=\"2.2\"/><text x=\"166\" y=\"404\" font-size=\"13\">skim</text><line x1=\"227\" y1=\"399\" x2=\"239\" y2=\"399\" class=\"s-muted\" stroke-width=\"2.2\" stroke-linecap=\"round\"/><text x=\"248\" y=\"404\" font-size=\"13\">skip for now</text></svg>"
